const item = $input.first();
const raw = item.json;
const isWebhook = 'body' in raw || 'headers' in raw;
const body = isWebhook ? (raw.body || {}) : {};
return [{
  json: {
    source: isWebhook ? 'webhook' : 'auto',
    force: body.force === true,
    lead_id: body.lead_id || null,
    proceed: true
  }
}];

const ctx = $json;
if (ctx.force === true) {
  return [{ json: { ...ctx, proceed: true, bypassed: true } }];
}
const now = new Date();
const estTime = new Date(now.toLocaleString('en-US', { timeZone: 'America/New_York' }));
const hour = estTime.getHours();
const day = estTime.getDay();
if (day === 0 || day === 6) {
  return [{ json: { ...ctx, proceed: false, reason: 'Weekend - no calls' } }];
}
if (hour < 8 || hour >= 17) {
  return [{ json: { ...ctx, proceed: false, reason: 'Outside business hours (8am-5pm EST)' } }];
}
return [{ json: { ...ctx, proceed: true, currentHour: hour, dayOfWeek: day } }];

const ctx = $json;
const leads = $('Leer Leads Pendientes').all();
let callsToday = 0;
try {
  const stats = $('Leer Stats del Día').all();
  if (stats.length > 0 && stats[0].json.total_calls) {
    callsToday = parseInt(stats[0].json.total_calls) || 0;
  }
} catch(e) { callsToday = 0; }

if (callsToday >= 25) {
  return [{ json: { proceed: false, reason: 'Daily limit reached (' + callsToday + '/25)', callsToday } }];
}

if (ctx.lead_id) {
  const specific = leads.find(l => String(l.json.id) === String(ctx.lead_id));
  if (specific) return [{ json: { ...specific.json, callsToday, proceed: true } }];
  return [{ json: { proceed: false, reason: 'Lead ID ' + ctx.lead_id + ' not found or ineligible', callsToday } }];
}

const seenPhones = new Set();
const valid = leads.filter(l => {
  const phone = String(l.json.phone || '').trim();
  if (!phone || seenPhones.has(phone)) return false;
  seenPhones.add(phone);
  return true;
}).slice(0, 1);

if (valid.length === 0) {
  return [{ json: { proceed: false, reason: 'No valid leads available', callsToday } }];
}
return valid.map(l => ({ json: { ...l.json, callsToday, proceed: true } }));

