const agentOutput = $input.all()[0];
const lead = $('¿Lead Válido?').first().json;
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
const script = agentOutput.json.output || agentOutput.json.text || '';

if (!script || script.length < 100) {
  throw new Error('AI Agent did not return a valid script. Output: ' + JSON.stringify(agentOutput.json));
}

return [{ json: {
  phone: lead.phone,
  lead_id: lead.id,
  lead_name: lead.lead_name || 'there',
  company: lead.company || '',
  email: lead.email || '',
  title: lead.title || '',
  lead_type: lead.lead_type || 'STAFFING',
  attempts: lead.attempts || 0,
  script: script,
  call_date_today: today
}}];

const BLAND_API_KEY = 'YOUR_BLAND_API_KEY_HERE';
const BLAND_WEBHOOK_URL = 'https://YOUR_N8N_INSTANCE/webhook/bland-callback';

const payload = $('Preparar Payload Bland').first().json;
const n = payload.lead_name;
const task = payload.script;

const body = {
  phone_number: payload.phone,
  task: task,
  voice: '4e65cda2-cf46-4907-84ba-3ca96c48f549',
  first_sentence: 'Hi, is this ' + n + '?',
  wait_for_greeting: false,
  noise_cancellation: true,
  background_track: 'office',
  record: true,
  max_duration: 5,
  language: 'en-US',
  model: 'enhanced',
  interruption_threshold: 200,
  temperature: 0.4,
  voice_settings: { speed: 1.0 },
  voicemail: {
    action: 'leave_message',
    message: 'Hi ' + n + ', this is Laura from MSI Technologies. We help companies scale their tech teams with senior nearshore engineers. I would love to connect briefly. Reach us at n-r-i-a-n-o at msiamericas dot com. Have a great day.'
  },
  summary_prompt: 'Analyze this sales call. Output: 1) disposition (exactly one of: meeting_scheduled, send_email, callback, not_interested, wrong_number, gatekeeper, voicemail, no_answer), 2) meeting_date and meeting_time if scheduled, 3) callback_date and callback_time if requested, 4) email_collected if confirmed character by character during call, 5) pain_points as comma-separated list of challenges mentioned, 6) summary as 2-3 sentence outcome.',
  dispositions: ['meeting_scheduled', 'send_email', 'callback', 'not_interested', 'wrong_number', 'gatekeeper', 'voicemail', 'no_answer'],
  pronunciation_guide: [
    { word: 'MSI', pronunciation: 'M-S-I', case_sensitive: true, spaced: true },
    { word: '5G', pronunciation: 'Five-G', case_sensitive: true, spaced: true },
    { word: 'IoT', pronunciation: 'I-O-T', case_sensitive: true, spaced: true },
    { word: 'AWS', pronunciation: 'A-W-S', case_sensitive: true, spaced: true },
    { word: 'GCP', pronunciation: 'G-C-P', case_sensitive: true, spaced: true }
  ],
  webhook: BLAND_WEBHOOK_URL,
  metadata: {
    lead_id: String(payload.lead_id || ''),
    lead_name: n,
    company: payload.company,
    email: payload.email,
    phone: payload.phone,
    lead_type: payload.lead_type || 'STAFFING',
    call_date: payload.call_date_today
  }
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.bland.ai/v1/calls',
  headers: {
    'Content-Type': 'application/json',
    'authorization': BLAND_API_KEY
  },
  body: body
});

if (!response.call_id) {
  throw new Error('Bland API error: ' + JSON.stringify(response));
}

return [{ json: {
  call_id: response.call_id,
  bland_status: response.status,
  phone: payload.phone,
  lead_id: payload.lead_id,
  lead_name: n,
  company: payload.company,
  email: payload.email,
  call_date_today: payload.call_date_today
}}];
